pub(crate) const ENDPOINT: &str =
    "https://thegencc.org/download/action/submissions-export-csv?format=new";
fn endpoint() -> String {
    if let Ok(value) = std::env::var("BIOMCP_GENCC_BASE")
        && (cfg!(debug_assertions) || fixture_override_allowed(&value))
    {
        return value;
    }
    ENDPOINT.to_string()
}

